using System.Globalization;

namespace KeorMon.UI;

/// <summary>
/// Lightweight localization for the 20 most spoken languages.
/// Each key maps to an array of translations in the fixed order of <see cref="Codes"/>;
/// lookup falls back to English (index 0) when a language or key is missing.
/// Set the language explicitly via <see cref="Initialize"/> ("auto" follows the OS).
/// </summary>
public static class L10n
{
    /// <summary>ISO 639-1 codes, fixed order. en, it first for readability; the rest by speakers.</summary>
    public static readonly string[] Codes =
        { "en", "it", "zh", "hi", "es", "fr", "ar", "bn", "pt", "ru", "ur", "id", "de", "ja", "mr", "te", "tr", "ta", "vi", "ko" };

    /// <summary>Native display names, same order as <see cref="Codes"/>.</summary>
    public static readonly string[] NativeNames =
        { "English", "Italiano", "中文", "हिन्दी", "Español", "Français", "العربية", "বাংলা", "Português", "Русский",
          "اردو", "Bahasa Indonesia", "Deutsch", "日本語", "मराठी", "తెలుగు", "Türkçe", "தமிழ்", "Tiếng Việt", "한국어" };

    private static int _lang;   // index into Codes

    public static void Initialize(string language)
    {
        var code = string.IsNullOrWhiteSpace(language) || language == "auto"
            ? CultureInfo.CurrentUICulture.TwoLetterISOLanguageName
            : language;
        _lang = Math.Max(0, Array.IndexOf(Codes, code));
    }

    public static string T(string key)
    {
        if (!S.TryGetValue(key, out var arr)) return key;
        var v = _lang < arr.Length ? arr[_lang] : null;
        return string.IsNullOrEmpty(v) ? arr[0] : v;
    }

    public static string F(string key, params object?[] args) => string.Format(T(key), args);

