        ["param_DelayBeforeReboot"] = new[] { "Output reboot delay", "Ritardo riavvio uscita", "输出重启延时", "आउटपुट रीबूट विलंब", "Retardo de reinicio de salida", "Délai de redémarrage de sortie", "مهلة إعادة تشغيل الخرج", "আউটপুট রিবুট বিলম্ব", "Atraso de reinício da saída", "Задержка перезапуска выхода", "آؤٹ پٹ ری بوٹ تاخیر", "Tunda mulai ulang keluaran", "Ausgangs-Neustartverzögerung", "出力再起動遅延", "आउटपुट रीबूट विलंब", "అవుట్‌పుట్ రీబూట్ ఆలస్యం", "Çıkış yeniden başlatma gecikmesi", "வெளியீட்டு மறுதொடக்க தாமதம்", "Trễ khởi động lại đầu ra", "출력 재시작 지연" },
        ["param_WarningCapacityLimit"] = new[] { "Capacity warning threshold", "Soglia avviso capacità", "容量警告阈值", "क्षमता चेतावनी सीमा", "Umbral de aviso de capacidad", "Seuil d'alerte de capacité", "عتبة تحذير السعة", "ক্ষমতা সতর্কতা সীমা", "Limite de aviso de capacidade", "Порог предупреждения ёмкости", "گنجائش انتباہ حد", "Ambang peringatan kapasitas", "Kapazitätswarnschwelle", "容量警告しきい値", "क्षमता इशारा मर्यादा", "కెపాసిటీ హెచ్చరిక పరిమితి", "Kapasite uyarı eşiği", "கொள்ளளவு எச்சரிக்கை வரம்பு", "Ngưỡng cảnh báo dung lượng", "용량 경고 임계값" },
        ["param_DelayBeforeStartup"] = new[] { "Output startup delay", "Ritardo avvio uscita", "输出启动延时", "आउटपुट स्टार्टअप विलंब", "Retardo de arranque de salida", "Délai de démarrage de sortie", "مهلة بدء الخرج", "আউটপুট স্টার্টআপ বিলম্ব", "Atraso de partida da saída", "Задержка запуска выхода", "آؤٹ پٹ اسٹارٹ اپ تاخیر", "Tunda mulai keluaran", "Ausgangs-Startverzögerung", "出力起動遅延", "आउटपुट सुरूवात विलंब", "అవుట్‌పుట్ స్టార్టప్ ఆలస్యం", "Çıkış başlatma gecikmesi", "வெளியீட்டு தொடக்க தாமதம்", "Trễ khởi động đầu ra", "출력 시작 지연" },

        // descriptions shown in Settings next to each monitor field / under the selected UPS parameter
        ["desc_LowVoltageTransfer"] = new[] { "Mains voltage below which the UPS switches to battery (inverter). Lower it if the UPS trips too often on a weak grid; the load will see a lower voltage before transfer.", "Tensione di rete sotto la quale l'UPS passa in batteria (inverter). Abbassala se l'UPS interviene troppo spesso con rete debole; il carico vedrà una tensione più bassa prima del trasferimento.", "市电电压低于此值时，UPS 切换到电池（逆变器）供电。电网较弱时若切换过于频繁可调低；切换前负载将承受更低电压。", "मुख्य वोल्टेज इससे नीचे जाने पर UPS बैटरी (इन्वर्टर) पर चला जाता है। कमजोर ग्रिड पर बार-बार स्विच हो तो इसे कम करें; स्थानांतरण से पहले लोड को कम वोल्टेज मिलेगा।", "Tensión de red por debajo de la cual el SAI pasa a batería (inversor). Bájala si el SAI conmuta demasiado a menudo con una red débil; la carga verá una tensión menor antes de la transferencia.", "Tension secteur sous laquelle l'onduleur passe sur batterie. Abaissez-la si l'onduleur bascule trop souvent sur un réseau faible ; la charge verra une tension plus basse avant le transfert.", "جهد الشبكة الذي يتحول تحته الجهاز إلى البطارية (العاكس). اخفضه إذا كان الجهاز يتحول كثيرًا مع شبكة ضعيفة؛ سيتعرض الحمل لجهد أقل قبل التحويل.", "এই ভোল্টেজের নিচে গেলে UPS ব্যাটারিতে (ইনভার্টার) চলে যায়। দুর্বল গ্রিডে ঘন ঘন সুইচ হলে কমান; ট্রান্সফারের আগে লোড কম ভোল্টেজ পাবে।", "Tensão da rede abaixo da qual o UPS passa para bateria (inversor). Reduza se o UPS comutar com demasiada frequência numa rede fraca; a carga verá uma tensão mais baixa antes da transferência.", "Напряжение сети, ниже которого ИБП переходит на батарею (инвертор). Понизьте, если ИБП слишком часто переключается в слабой сети; нагрузка увидит более низкое напряжение до перехода.", "مینز وولٹیج جس سے نیچے UPS بیٹری (انورٹر) پر چلا جاتا ہے۔ کمزور گرڈ پر بار بار سوئچ ہو تو کم کریں؛ ٹرانسفر سے پہلے لوڈ کو کم وولٹیج ملے گا۔", "Tegangan jala-jala di bawah nilai ini membuat UPS beralih ke baterai (inverter). Turunkan jika UPS terlalu sering beralih pada jaringan lemah; beban akan menerima tegangan lebih rendah sebelum transfer.", "Netzspannung, unter der die USV auf Batterie (Wechselrichter) umschaltet. Senken, wenn die USV bei schwachem Netz zu oft umschaltet; die Last sieht vor dem Umschalten eine niedrigere Spannung.", "この電圧を下回ると UPS はバッテリー（インバーター）運転に切り替わります。電源が不安定で切替が頻発する場合は下げてください。切替前に負荷へ供給される電圧は低くなります。", "मुख्य व्होल्टेज याखाली गेल्यास UPS बॅटरी (इन्व्हर्टर) वर जातो. कमकुवत ग्रिडवर वारंवार स्विच होत असल्यास कमी करा; ट्रान्सफरपूर्वी लोडला कमी व्होल्टेज मिळेल.", "ఈ వోల్టేజ్ కంటే తక్కువైతే UPS బ్యాటరీ (ఇన్వర్టర్) కి మారుతుంది. బలహీన గ్రిడ్‌లో తరచుగా మారుతుంటే తగ్గించండి; బదిలీకి ముందు లోడ్‌కు తక్కువ వోల్టేజ్ వస్తుంది.", "Şebeke gerilimi bu değerin altına indiğinde UPS aküye (invertöre) geçer. Zayıf şebekede UPS çok sık geçiş yapıyorsa düşürün; yük, geçişten önce daha düşük gerilim görür.", "இந்த மின்னழுத்தத்திற்குக் கீழே UPS மின்கலத்திற்கு (இன்வெர்ட்டர்) மாறும். பலவீன மின்சாரத்தில் அடிக்கடி மாறினால் குறைக்கவும்; மாற்றத்திற்கு முன் சுமைக்கு குறைந்த மின்னழுத்தம் கிடைக்கும்.", "Điện áp lưới dưới mức này thì UPS chuyển sang pin (inverter). Hạ thấp nếu UPS chuyển quá thường xuyên trên lưới yếu; tải sẽ nhận điện áp thấp hơn trước khi chuyển.", "이 값 미만의 입력 전압에서 UPS가 배터리(인버터)로 전환됩니다. 전원이 불안정해 전환이 잦으면 낮추세요. 전환 전까지 부하에 더 낮은 전압이 공급됩니다." },
        ["desc_HighVoltageTransfer"] = new[] { "Mains voltage above which the UPS switches to battery to protect the load from overvoltage. Raise it only if the grid is stable but slightly high and the UPS trips too often.", "Tensione di rete sopra la quale l'UPS passa in batteria per proteggere il carico da sovratensione. Alzala solo se la rete è stabile ma leggermente alta e l'UPS interviene troppo spesso.", "市电电压高于此值时，UPS 切换到电池以保护负载免受过压。仅当电网稳定但略高且切换过于频繁时才调高。", "मुख्य वोल्टेज इससे ऊपर जाने पर UPS ओवरवोल्टेज से लोड की रक्षा के लिए बैटरी पर चला जाता है। केवल तब बढ़ाएँ जब ग्रिड स्थिर पर थोड़ा ऊँचा हो और UPS बार-बार स्विच करे।", "Tensión de red por encima de la cual el SAI pasa a batería para proteger la carga de sobretensión. Súbela solo si la red es estable pero algo alta y el SAI conmuta demasiado.", "Tension secteur au-dessus de laquelle l'onduleur passe sur batterie pour protéger la charge des surtensions. Augmentez-la seulement si le réseau est stable mais un peu élevé et que l'onduleur bascule trop souvent.", "جهد الشبكة الذي يتحول فوقه الجهاز إلى البطارية لحماية الحمل من الجهد الزائد. ارفعه فقط إذا كانت الشبكة مستقرة لكن مرتفعة قليلًا والجهاز يتحول كثيرًا.", "এই ভোল্টেজের উপরে গেলে ওভারভোল্টেজ থেকে লোড রক্ষায় UPS ব্যাটারিতে যায়। গ্রিড স্থির কিন্তু কিছুটা উঁচু হলে এবং ঘন ঘন সুইচ হলে কেবল তখনই বাড়ান।", "Tensão da rede acima da qual o UPS passa para bateria para proteger a carga de sobretensão. Aumente apenas se a rede for estável mas ligeiramente alta e o UPS comutar demasiado.", "Напряжение сети, выше которого ИБП переходит на батарею для защиты нагрузки от перенапряжения. Повышайте только если сеть стабильна, но слегка завышена и ИБП переключается слишком часто.", "مینز وولٹیج جس سے اوپر UPS اوور وولٹیج سے لوڈ بچانے کے لیے بیٹری پر جاتا ہے۔ صرف تب بڑھائیں جب گرڈ مستحکم مگر تھوڑا زیادہ ہو اور UPS بار بار سوئچ کرے۔", "Tegangan jala-jala di atas nilai ini membuat UPS beralih ke baterai untuk melindungi beban dari tegangan lebih. Naikkan hanya jika jaringan stabil tetapi agak tinggi dan UPS terlalu sering beralih.", "Netzspannung, über der die USV zum Schutz der Last vor Überspannung auf Batterie umschaltet. Nur erhöhen, wenn das Netz stabil aber leicht zu hoch ist und die USV zu oft umschaltet.", "この電圧を上回ると、過電圧から負荷を守るため UPS はバッテリー運転に切り替わります。電源が安定しているがやや高く、切替が頻発する場合のみ上げてください。", "मुख्य व्होल्टेज याच्या वर गेल्यास ओव्हरव्होल्टेजपासून लोड वाचवण्यासाठी UPS बॅटरीवर जातो. ग्रिड स्थिर पण किंचित जास्त असेल आणि UPS वारंवार स्विच होत असेल तरच वाढवा.", "ఈ వోల్టేజ్ కంటే ఎక్కువైతే ఓవర్‌వోల్టేజ్ నుండి లోడ్‌ను రక్షించడానికి UPS బ్యాటరీకి మారుతుంది. గ్రిడ్ స్థిరంగా కానీ కొంచెం ఎక్కువగా ఉండి UPS తరచుగా మారుతుంటే మాత్రమే పెంచండి.", "Şebeke gerilimi bu değerin üstüne çıktığında UPS, yükü aşırı gerilimden korumak için aküye geçer. Yalnızca şebeke kararlı ama biraz yüksekse ve UPS çok sık geçiş yapıyorsa yükseltin.", "இந்த மின்னழுத்தத்திற்கு மேல் சுமையை அதிக மின்னழுத்தத்திலிருந்து காக்க UPS மின்கலத்திற்கு மாறும். மின்சாரம் நிலையாக ஆனால் சற்று அதிகமாக இருந்து அடிக்கடி மாறினால் மட்டும் உயர்த்தவும்.", "Điện áp lưới trên mức này thì UPS chuyển sang pin để bảo vệ tải khỏi quá áp. Chỉ tăng nếu lưới ổn định nhưng hơi cao và UPS chuyển quá thường xuyên.", "이 값 초과의 입력 전압에서 과전압으로부터 부하를 보호하기 위해 UPS가 배터리로 전환됩니다. 전원이 안정적이지만 약간 높고 전환이 잦을 때만 올리세요." },
        ["desc_Test"] = new[] { "Battery self-test command (HID standard codes). Write 1 = quick test, 2 = deep test (to low battery), 3 = abort. Readback: 4 = passed, 5 = warning, 6 = error, 0 = none.", "Comando di autotest batteria (codici standard HID). Scrivi 1 = test rapido, 2 = test profondo (fino a batteria bassa), 3 = interrompi. Rilettura: 4 = superato, 5 = avviso, 6 = errore, 0 = nessuno.", "电池自检命令（HID 标准代码）。写入 1 = 快速测试，2 = 深度测试（放电至低电量），3 = 中止。回读：4 = 通过，5 = 警告，6 = 错误，0 = 无。", "बैटरी स्व-परीक्षण आदेश (HID मानक कोड)। लिखें 1 = त्वरित परीक्षण, 2 = गहन परीक्षण (कम बैटरी तक), 3 = रद्द। रीडबैक: 4 = सफल, 5 = चेतावनी, 6 = त्रुटि, 0 = कोई नहीं।", "Comando de autoprueba de batería (códigos estándar HID). Escribe 1 = prueba rápida, 2 = prueba profunda (hasta batería baja), 3 = abortar. Lectura: 4 = superada, 5 = aviso, 6 = error, 0 = ninguna.", "Commande d'autotest batterie (codes HID standard). Écrire 1 = test rapide, 2 = test approfondi (jusqu'à batterie faible), 3 = annuler. Relecture : 4 = réussi, 5 = avertissement, 6 = erreur, 0 = aucun.", "أمر الاختبار الذاتي للبطارية (رموز HID القياسية). اكتب 1 = اختبار سريع، 2 = اختبار عميق (حتى انخفاض البطارية)، 3 = إلغاء. القراءة: 4 = ناجح، 5 = تحذير، 6 = خطأ، 0 = لا شيء.", "ব্যাটারি সেলফ-টেস্ট কমান্ড (HID স্ট্যান্ডার্ড কোড)। লিখুন 1 = দ্রুত পরীক্ষা, 2 = গভীর পরীক্ষা (কম ব্যাটারি পর্যন্ত), 3 = বাতিল। রিডব্যাক: 4 = পাস, 5 = সতর্কতা, 6 = ত্রুটি, 0 = কিছু নয়।", "Comando de autoteste da bateria (códigos HID padrão). Escreva 1 = teste rápido, 2 = teste profundo (até bateria fraca), 3 = abortar. Leitura: 4 = aprovado, 5 = aviso, 6 = erro, 0 = nenhum.", "Команда самотеста батареи (стандартные коды HID). Запись 1 = быстрый тест, 2 = глубокий тест (до низкого заряда), 3 = прервать. Чтение: 4 = пройден, 5 = предупреждение, 6 = ошибка, 0 = нет.", "بیٹری سیلف ٹیسٹ کمانڈ (HID معیاری کوڈ)۔ لکھیں 1 = فوری ٹیسٹ، 2 = گہرا ٹیسٹ (کم بیٹری تک)، 3 = منسوخ۔ ریڈ بیک: 4 = کامیاب، 5 = انتباہ، 6 = خرابی، 0 = کوئی نہیں۔", "Perintah uji mandiri baterai (kode standar HID). Tulis 1 = uji cepat, 2 = uji mendalam (hingga baterai lemah), 3 = batalkan. Baca kembali: 4 = lulus, 5 = peringatan, 6 = kesalahan, 0 = tidak ada.", "Akku-Selbsttest-Befehl (HID-Standardcodes). Schreiben: 1 = Schnelltest, 2 = Tieftest (bis Akku schwach), 3 = Abbruch. Rücklesen: 4 = bestanden, 5 = Warnung, 6 = Fehler, 0 = keiner.", "バッテリー自己診断コマンド（HID 標準コード）。書込み 1 = クイックテスト、2 = ディープテスト（バッテリー低下まで）、3 = 中止。読出し：4 = 合格、5 = 警告、6 = エラー、0 = なし。", "बॅटरी स्व-चाचणी आदेश (HID मानक कोड). लिहा 1 = जलद चाचणी, 2 = सखोल चाचणी (कमी बॅटरीपर्यंत), 3 = रद्द. रीडबॅक: 4 = उत्तीर्ण, 5 = इशारा, 6 = त्रुटी, 0 = काही नाही.", "బ్యాటరీ స్వీయ-పరీక్ష కమాండ్ (HID ప్రామాణిక కోడ్‌లు). రాయండి 1 = త్వరిత పరీక్ష, 2 = లోతైన పరీక్ష (తక్కువ బ్యాటరీ వరకు), 3 = రద్దు. రీడ్‌బ్యాక్: 4 = ఉత్తీర్ణత, 5 = హెచ్చరిక, 6 = లోపం, 0 = ఏదీ లేదు.", "Akü kendini test komutu (HID standart kodları). Yaz: 1 = hızlı test, 2 = derin test (düşük aküye kadar), 3 = iptal. Geri okuma: 4 = başarılı, 5 = uyarı, 6 = hata, 0 = yok.", "மின்கல சுய சோதனை கட்டளை (HID நிலையான குறியீடுகள்). எழுதுக 1 = விரைவு சோதனை, 2 = ஆழ சோதனை (குறைந்த மின்கலம் வரை), 3 = ரத்து. திரும்ப வாசிப்பு: 4 = வெற்றி, 5 = எச்சரிக்கை, 6 = பிழை, 0 = இல்லை.", "Lệnh tự kiểm tra pin (mã chuẩn HID). Ghi 1 = kiểm tra nhanh, 2 = kiểm tra sâu (đến pin yếu), 3 = hủy. Đọc lại: 4 = đạt, 5 = cảnh báo, 6 = lỗi, 0 = không.", "배터리 자체 테스트 명령(HID 표준 코드). 쓰기 1 = 빠른 테스트, 2 = 심층 테스트(배터리 부족까지), 3 = 중단. 읽기: 4 = 통과, 5 = 경고, 6 = 오류, 0 = 없음." },
        ["desc_AudibleAlarmControl"] = new[] { "Controls the buzzer: 1 = disabled, 2 = enabled (beeps on battery, low battery, overload), 3 = muted (silences the current alarm). The physical button on the UPS changes this value too.", "Controlla il buzzer: 1 = disabilitato, 2 = abilitato (suona in batteria, batteria bassa, sovraccarico), 3 = silenziato (tace l'allarme in corso). Anche il tasto fisico sull'UPS modifica questo valore.", "控制蜂鸣器：1 = 禁用，2 = 启用（电池供电、低电量、过载时鸣叫），3 = 静音（消除当前警报）。UPS 上的物理按钮也会改变此值。", "बज़र नियंत्रण: 1 = अक्षम, 2 = सक्षम (बैटरी, कम बैटरी, ओवरलोड पर बीप), 3 = मूक (वर्तमान अलार्म शांत)। UPS का भौतिक बटन भी यह मान बदलता है।", "Controla el zumbador: 1 = desactivado, 2 = activado (suena en batería, batería baja, sobrecarga), 3 = silenciado (calla la alarma actual). El botón físico del SAI también cambia este valor.", "Contrôle le buzzer : 1 = désactivé, 2 = activé (bipe sur batterie, batterie faible, surcharge), 3 = muet (coupe l'alarme en cours). Le bouton physique de l'onduleur modifie aussi cette valeur.", "يتحكم في الجرس: 1 = معطّل، 2 = مفعّل (يصفر عند البطارية، البطارية المنخفضة، الحمل الزائد)، 3 = صامت (يُسكت الإنذار الحالي). زر الجهاز الفعلي يغيّر هذه القيمة أيضًا.", "বাজার নিয়ন্ত্রণ: 1 = নিষ্ক্রিয়, 2 = সক্রিয় (ব্যাটারি, কম ব্যাটারি, ওভারলোডে বিপ), 3 = নিঃশব্দ (বর্তমান অ্যালার্ম বন্ধ)। UPS-এর বোতামও এই মান বদলায়।", "Controla o sinal sonoro: 1 = desativado, 2 = ativado (apita em bateria, bateria fraca, sobrecarga), 3 = silenciado (cala o alarme atual). O botão físico do UPS também altera este valor.", "Управление зуммером: 1 = отключён, 2 = включён (сигнал на батарее, при низком заряде, перегрузке), 3 = заглушён (гасит текущий сигнал). Кнопка на ИБП тоже меняет это значение.", "بزر کنٹرول: 1 = غیر فعال، 2 = فعال (بیٹری، کم بیٹری، اوورلوڈ پر بیپ)، 3 = خاموش (موجودہ الارم بند)۔ UPS کا جسمانی بٹن بھی یہ قدر بدلتا ہے۔", "Mengatur bel: 1 = nonaktif, 2 = aktif (berbunyi saat baterai, baterai lemah, kelebihan beban), 3 = senyap (membisukan alarm saat ini). Tombol fisik pada UPS juga mengubah nilai ini.", "Steuert den Summer: 1 = deaktiviert, 2 = aktiviert (piept bei Batteriebetrieb, schwachem Akku, Überlast), 3 = stumm (stellt den aktuellen Alarm ab). Die Taste an der USV ändert diesen Wert ebenfalls.", "ブザー制御：1 = 無効、2 = 有効（バッテリー運転・バッテリー低下・過負荷で鳴動）、3 = ミュート（現在の警報を消音）。UPS 本体のボタンでもこの値が変わります。", "बझर नियंत्रण: 1 = अक्षम, 2 = सक्षम (बॅटरी, कमी बॅटरी, ओव्हरलोडवर बीप), 3 = मूक (चालू अलार्म शांत). UPS वरील बटणही हे मूल्य बदलते.", "బజర్ నియంత్రణ: 1 = నిలిపివేయబడింది, 2 = ప్రారంభించబడింది (బ్యాటరీ, తక్కువ బ్యాటరీ, ఓవర్‌లోడ్‌లో బీప్), 3 = మ్యూట్ (ప్రస్తుత అలారం నిశ్శబ్దం). UPS పై బటన్ కూడా ఈ విలువను మారుస్తుంది.", "Sesli uyarıcıyı kontrol eder: 1 = devre dışı, 2 = etkin (aküde, düşük aküde, aşırı yükte öter), 3 = sessiz (mevcut alarmı susturur). UPS üzerindeki fiziksel düğme de bu değeri değiştirir.", "ஒலிப்பானைக் கட்டுப்படுத்தும்: 1 = முடக்கம், 2 = இயக்கம் (மின்கலம், குறைந்த மின்கலம், அதிக சுமையில் ஒலி), 3 = அமைதி (தற்போதைய எச்சரிக்கை நிறுத்தம்). UPS இன் பொத்தானும் இந்த மதிப்பை மாற்றும்.", "Điều khiển còi: 1 = tắt, 2 = bật (kêu khi chạy pin, pin yếu, quá tải), 3 = im lặng (tắt cảnh báo hiện tại). Nút vật lý trên UPS cũng thay đổi giá trị này.", "경고음 제어: 1 = 사용 안 함, 2 = 사용(배터리 운전, 배터리 부족, 과부하 시 울림), 3 = 무음(현재 경보 소거). UPS 본체 버튼으로도 이 값이 바뀝니다." },
        ["desc_DelayBeforeShutdown"] = new[] { "Seconds after which the UPS cuts power to its outlets. Writing a value starts the countdown immediately: everything connected loses power when it expires. 65535 (0xFFFF) = no countdown active.", "Secondi dopo i quali l'UPS toglie corrente alle prese. Scrivere un valore avvia subito il conto alla rovescia: allo scadere tutto ciò che è collegato perde alimentazione. 65535 (0xFFFF) = nessun conto alla rovescia attivo.", "UPS 切断输出插座供电前的秒数。写入即立刻开始倒计时：到期后所有连接设备断电。65535 (0xFFFF) = 无倒计时。", "सेकंड जिसके बाद UPS आउटलेट की बिजली काट देता है। मान लिखने से उलटी गिनती तुरंत शुरू होती है: समाप्ति पर जुड़े सभी उपकरण बंद हो जाते हैं। 65535 (0xFFFF) = कोई उलटी गिनती नहीं।", "Segundos tras los cuales el SAI corta la alimentación de sus tomas. Escribir un valor inicia la cuenta atrás de inmediato: al expirar, todo lo conectado pierde alimentación. 65535 (0xFFFF) = sin cuenta atrás activa.", "Secondes après lesquelles l'onduleur coupe l'alimentation de ses prises. Écrire une valeur lance immédiatement le décompte : à l'échéance, tout ce qui est branché perd l'alimentation. 65535 (0xFFFF) = aucun décompte actif.", "الثواني التي يقطع بعدها الجهاز الطاقة عن منافذه. كتابة قيمة تبدأ العد التنازلي فورًا: عند انتهائه تنقطع الطاقة عن كل ما هو متصل. 65535 (0xFFFF) = لا عد تنازلي نشط.", "এই সেকেন্ড পরে UPS আউটলেটের বিদ্যুৎ বন্ধ করে। মান লিখলে সাথে সাথে কাউন্টডাউন শুরু হয়: শেষ হলে সংযুক্ত সবকিছু বন্ধ হয়। 65535 (0xFFFF) = কোনো কাউন্টডাউন নেই।", "Segundos após os quais o UPS corta a energia das tomadas. Escrever um valor inicia a contagem imediatamente: ao terminar, tudo o que está ligado perde energia. 65535 (0xFFFF) = nenhuma contagem ativa.", "Секунды, через которые ИБП отключает питание розеток. Запись значения сразу запускает отсчёт: по его окончании всё подключённое обесточивается. 65535 (0xFFFF) = отсчёт не активен.", "سیکنڈ جن کے بعد UPS آؤٹ لیٹس کی بجلی کاٹ دیتا ہے۔ قدر لکھنے سے الٹی گنتی فوراً شروع ہوتی ہے: ختم ہونے پر منسلک سب کچھ بند ہو جاتا ہے۔ 65535 (0xFFFF) = کوئی گنتی فعال نہیں۔", "Detik setelah UPS memutus daya ke stopkontaknya. Menulis nilai langsung memulai hitung mundur: saat habis, semua yang terhubung kehilangan daya. 65535 (0xFFFF) = tidak ada hitung mundur aktif.", "Sekunden, nach denen die USV die Steckdosen abschaltet. Das Schreiben eines Werts startet sofort den Countdown: nach Ablauf verlieren alle angeschlossenen Geräte die Versorgung. 65535 (0xFFFF) = kein Countdown aktiv.", "UPS が出力コンセントの給電を停止するまでの秒数。値を書き込むと即座にカウントダウンが開始され、満了時に接続機器すべての電源が落ちます。65535 (0xFFFF) = カウントダウンなし。", "सेकंद ज्यानंतर UPS आउटलेटची वीज तोडतो. मूल्य लिहिल्यास काउंटडाउन लगेच सुरू होतो: संपल्यावर जोडलेले सर्व बंद होते. 65535 (0xFFFF) = काउंटडाउन सक्रिय नाही.", "ఈ సెకన్ల తర్వాత UPS అవుట్‌లెట్ల విద్యుత్ నిలిపివేస్తుంది. విలువ రాస్తే కౌంట్‌డౌన్ వెంటనే ప్రారంభమవుతుంది: ముగిసినపుడు కనెక్ట్ అయిన ప్రతిదీ ఆగిపోతుంది. 65535 (0xFFFF) = కౌంట్‌డౌన్ లేదు.", "UPS'in prizlerinin gücünü kestiği saniye. Bir değer yazmak geri sayımı hemen başlatır: süre dolunca bağlı her şey gücünü kaybeder. 65535 (0xFFFF) = etkin geri sayım yok.", "UPS தனது வெளியீட்டு இணைப்புகளுக்கு மின்சாரத்தை நிறுத்தும் நொடிகள். மதிப்பு எழுதினால் உடனே எண்ணிக்கை தொடங்கும்: முடிந்தவுடன் இணைக்கப்பட்ட எல்லாமும் மின்சாரம் இழக்கும். 65535 (0xFFFF) = எண்ணிக்கை இல்லை.", "Số giây sau đó UPS ngắt điện các ổ cắm. Ghi giá trị sẽ bắt đầu đếm ngược ngay: khi hết, mọi thiết bị đang nối mất điện. 65535 (0xFFFF) = không có đếm ngược.", "UPS가 출력 콘센트 전원을 차단하기까지의 초. 값을 쓰면 즉시 카운트다운이 시작되며 만료 시 연결된 모든 장비의 전원이 끊깁니다. 65535 (0xFFFF) = 카운트다운 없음." },
        ["desc_DelayBeforeReboot"] = new[] { "Seconds the outlets stay off after a shutdown before the UPS restores output. Used together with the shutdown delay to power-cycle the connected devices. 65535 (0xFFFF) = not set.", "Secondi in cui le prese restano spente dopo uno spegnimento prima che l'UPS ripristini l'uscita. Si usa insieme al ritardo di spegnimento per riavviare (power-cycle) i dispositivi collegati. 65535 (0xFFFF) = non impostato.", "关机后插座保持断电、直到 UPS 恢复输出的秒数。与关机延时配合用于给连接设备断电重启。65535 (0xFFFF) = 未设置。", "शटडाउन के बाद UPS आउटपुट बहाल करने से पहले आउटलेट कितने सेकंड बंद रहें। जुड़े उपकरणों को पावर-साइकल करने के लिए शटडाउन विलंब के साथ प्रयोग करें। 65535 (0xFFFF) = सेट नहीं।", "Segundos que las tomas permanecen apagadas tras un apagado antes de que el SAI restaure la salida. Se usa con el retardo de apagado para reiniciar (power-cycle) los equipos conectados. 65535 (0xFFFF) = no definido.", "Secondes pendant lesquelles les prises restent coupées après un arrêt avant que l'onduleur ne rétablisse la sortie. À utiliser avec le délai de coupure pour redémarrer électriquement les appareils. 65535 (0xFFFF) = non défini.", "الثواني التي تبقى فيها المنافذ مطفأة بعد الإيقاف قبل أن يعيد الجهاز الخرج. يُستخدم مع مهلة الإيقاف لإعادة تشغيل الأجهزة المتصلة كهربائيًا. 65535 (0xFFFF) = غير محدد.", "শাটডাউনের পরে UPS আউটপুট ফেরানোর আগে আউটলেট কত সেকেন্ড বন্ধ থাকবে। সংযুক্ত ডিভাইস পাওয়ার-সাইকেল করতে শাটডাউন বিলম্বের সাথে ব্যবহার হয়। 65535 (0xFFFF) = সেট নেই।", "Segundos em que as tomadas ficam desligadas após um desligamento antes de o UPS repor a saída. Usado com o atraso de desligamento para reiniciar (power-cycle) os equipamentos. 65535 (0xFFFF) = não definido.", "Секунды, в течение которых розетки остаются выключенными после отключения, прежде чем ИБП восстановит выход. Используется вместе с задержкой отключения для перезапуска устройств по питанию. 65535 (0xFFFF) = не задано.", "شٹ ڈاؤن کے بعد UPS آؤٹ پٹ بحال کرنے سے پہلے آؤٹ لیٹس کتنے سیکنڈ بند رہیں۔ منسلک آلات کو پاور سائیکل کرنے کے لیے شٹ ڈاؤن تاخیر کے ساتھ استعمال ہوتا ہے۔ 65535 (0xFFFF) = سیٹ نہیں۔", "Detik stopkontak tetap mati setelah pemadaman sebelum UPS memulihkan keluaran. Digunakan bersama tunda pemadaman untuk menyalakan ulang perangkat terhubung. 65535 (0xFFFF) = tidak diatur.", "Sekunden, die die Steckdosen nach einer Abschaltung aus bleiben, bevor die USV den Ausgang wieder einschaltet. Zusammen mit der Abschaltverzögerung zum Neustarten (Power-Cycle) der Geräte. 65535 (0xFFFF) = nicht gesetzt.", "シャットダウン後、UPS が出力を復帰するまでコンセントをオフに保つ秒数。遮断遅延と組み合わせて接続機器の電源再投入に使います。65535 (0xFFFF) = 未設定。", "शटडाउननंतर UPS आउटपुट पूर्ववत करण्यापूर्वी आउटलेट किती सेकंद बंद राहतील. जोडलेली उपकरणे पॉवर-सायकल करण्यासाठी शटडाउन विलंबासह वापरा. 65535 (0xFFFF) = सेट नाही.", "షట్‌డౌన్ తర్వాత UPS అవుట్‌పుట్ పునరుద్ధరించే ముందు అవుట్‌లెట్లు ఎన్ని సెకన్లు ఆఫ్‌గా ఉంటాయో. కనెక్ట్ అయిన పరికరాలను పవర్-సైకిల్ చేయడానికి షట్‌డౌన్ ఆలస్యంతో వాడతారు. 65535 (0xFFFF) = సెట్ కాలేదు.", "Kapatmadan sonra UPS çıkışı geri vermeden önce prizlerin kapalı kaldığı saniye. Bağlı cihazları kapat-aç yapmak için kapatma gecikmesiyle birlikte kullanılır. 65535 (0xFFFF) = ayarlı değil.", "நிறுத்தத்திற்குப் பின் UPS வெளியீட்டை மீட்டெடுக்கும் முன் இணைப்புகள் அணைந்திருக்கும் நொடிகள். இணைந்த சாதனங்களை மின் மறுதொடக்கம் செய்ய நிறுத்த தாமதத்துடன் பயன்படும். 65535 (0xFFFF) = அமைக்கப்படவில்லை.", "Số giây ổ cắm tắt sau khi ngắt trước khi UPS khôi phục đầu ra. Dùng cùng trễ ngắt để khởi động lại nguồn cho các thiết bị đang nối. 65535 (0xFFFF) = chưa đặt.", "차단 후 UPS가 출력을 복구하기 전까지 콘센트가 꺼져 있는 초. 차단 지연과 함께 연결 장비의 전원 재투입에 사용합니다. 65535 (0xFFFF) = 미설정." },
        ["desc_WarningCapacityLimit"] = new[] { "Battery charge percentage below which the UPS reports \"low battery\" (status flag and buzzer). Does not shut anything down; the monitor thresholds on the left are separate.", "Percentuale di carica sotto la quale l'UPS segnala \"batteria bassa\" (flag di stato e buzzer). Non spegne nulla; le soglie del monitor a sinistra sono indipendenti.", "电池电量低于此百分比时 UPS 报告“低电量”（状态标志和蜂鸣器）。不会关闭任何设备；左侧监控阈值与此独立。", "बैटरी चार्ज प्रतिशत जिससे नीचे UPS \"कम बैटरी\" रिपोर्ट करता है (स्थिति फ्लैग और बज़र)। कुछ बंद नहीं करता; बाईं ओर की मॉनिटर सीमाएँ अलग हैं।", "Porcentaje de carga por debajo del cual el SAI señala \"batería baja\" (indicador de estado y zumbador). No apaga nada; los umbrales del monitor a la izquierda son independientes.", "Pourcentage de charge sous lequel l'onduleur signale « batterie faible » (drapeau d'état et buzzer). N'arrête rien ; les seuils du moniteur à gauche sont indépendants.", "نسبة شحن البطارية التي يبلّغ الجهاز تحتها عن \"بطارية منخفضة\" (علم الحالة والجرس). لا يوقف شيئًا؛ عتبات المراقبة على اليسار مستقلة.", "এই চার্জ শতাংশের নিচে UPS \"কম ব্যাটারি\" জানায় (স্ট্যাটাস ফ্ল্যাগ ও বাজার)। কিছু বন্ধ করে না; বামের মনিটর সীমা আলাদা।", "Percentagem de carga abaixo da qual o UPS sinaliza \"bateria fraca\" (indicador de estado e sinal sonoro). Não desliga nada; os limites do monitor à esquerda são independentes.", "Процент заряда, ниже которого ИБП сообщает «низкий заряд» (флаг состояния и зуммер). Ничего не отключает; пороги монитора слева независимы.", "بیٹری چارج فیصد جس سے نیچے UPS \"کم بیٹری\" رپورٹ کرتا ہے (سٹیٹس فلیگ اور بزر)۔ کچھ بند نہیں کرتا؛ بائیں جانب مانیٹر کی حدیں الگ ہیں۔", "Persentase daya baterai di bawah nilai ini membuat UPS melaporkan \"baterai lemah\" (bendera status dan bel). Tidak mematikan apa pun; ambang monitor di kiri terpisah.", "Ladezustand in Prozent, unter dem die USV „Akku schwach“ meldet (Statusflag und Summer). Schaltet nichts ab; die Monitor-Schwellen links sind unabhängig.", "この残量（%）を下回ると UPS が「バッテリー低下」を報告します（ステータスフラグとブザー）。何も停止しません。左側のモニターしきい値は別です。", "बॅटरी चार्ज टक्केवारी ज्याखाली UPS \"कमी बॅटरी\" नोंदवतो (स्टेटस फ्लॅग व बझर). काही बंद करत नाही; डावीकडील मॉनिटर मर्यादा स्वतंत्र आहेत.", "ఈ ఛార్జ్ శాతం కంటే తక్కువైతే UPS \"తక్కువ బ్యాటరీ\" నివేదిస్తుంది (స్టేటస్ ఫ్లాగ్, బజర్). ఏదీ ఆపదు; ఎడమవైపు మానిటర్ పరిమితులు వేరు.", "Akü şarjı bu yüzdenin altına indiğinde UPS \"düşük akü\" bildirir (durum bayrağı ve sesli uyarıcı). Hiçbir şeyi kapatmaz; soldaki izleme eşikleri ayrıdır.", "இந்த சார்ஜ் சதவீதத்திற்குக் கீழே UPS \"குறைந்த மின்கலம்\" என அறிவிக்கும் (நிலைக் கொடி மற்றும் ஒலிப்பான்). எதையும் நிறுத்தாது; இடப்புற கண்காணிப்பு வரம்புகள் தனி.", "Phần trăm pin dưới mức này thì UPS báo \"pin yếu\" (cờ trạng thái và còi). Không tắt gì; ngưỡng giám sát bên trái là riêng.", "이 충전율 미만에서 UPS가 \"배터리 부족\"을 보고합니다(상태 플래그와 경고음). 아무것도 끄지 않으며 왼쪽 모니터 임계값은 별개입니다." },
        ["desc_DelayBeforeStartup"] = new[] { "Seconds the UPS waits before energizing its outlets when it turns on or when mains returns after a shutdown. Lets upstream equipment (router, NAS) settle before the rest powers up. 65535 (0xFFFF) = not set.", "Secondi che l'UPS attende prima di alimentare le prese all'accensione o al ritorno della rete dopo uno spegnimento. Consente alle apparecchiature a monte (router, NAS) di stabilizzarsi prima di accendere il resto. 65535 (0xFFFF) = non impostato.", "UPS 开机或关机后市电恢复时，等待多少秒再给插座供电。让上游设备（路由器、NAS）先稳定再启动其余设备。65535 (0xFFFF) = 未设置。", "चालू होने पर या शटडाउन के बाद बिजली लौटने पर UPS आउटलेट को बिजली देने से पहले कितने सेकंड प्रतीक्षा करे। अपस्ट्रीम उपकरण (राउटर, NAS) को स्थिर होने देता है। 65535 (0xFFFF) = सेट नहीं।", "Segundos que el SAI espera antes de alimentar las tomas al encenderse o al volver la red tras un apagado. Permite que los equipos aguas arriba (router, NAS) se estabilicen antes de arrancar el resto. 65535 (0xFFFF) = no definido.", "Secondes d'attente avant que l'onduleur n'alimente ses prises à la mise sous tension ou au retour du secteur après un arrêt. Laisse les équipements amont (routeur, NAS) se stabiliser avant le reste. 65535 (0xFFFF) = non défini.", "الثواني التي ينتظرها الجهاز قبل تغذية منافذه عند التشغيل أو عند عودة الشبكة بعد الإيقاف. يتيح استقرار الأجهزة الأولية (الموجه، NAS) قبل تشغيل البقية. 65535 (0xFFFF) = غير محدد.", "চালু হওয়ার সময় বা শাটডাউনের পরে মেইন ফিরলে আউটলেটে বিদ্যুৎ দিতে UPS কত সেকেন্ড অপেক্ষা করবে। আপস্ট্রিম ডিভাইস (রাউটার, NAS) স্থির হতে দেয়। 65535 (0xFFFF) = সেট নেই।", "Segundos que o UPS aguarda antes de alimentar as tomadas ao ligar ou quando a rede regressa após um desligamento. Permite que o equipamento a montante (router, NAS) estabilize antes do resto. 65535 (0xFFFF) = não definido.", "Секунды ожидания перед подачей питания на розетки при включении ИБП или возврате сети после отключения. Даёт оборудованию выше по цепи (роутер, NAS) стабилизироваться до остального. 65535 (0xFFFF) = не задано.", "آن ہونے پر یا شٹ ڈاؤن کے بعد مینز واپس آنے پر UPS آؤٹ لیٹس کو بجلی دینے سے پہلے کتنے سیکنڈ انتظار کرے۔ اپ اسٹریم آلات (راؤٹر، NAS) کو مستحکم ہونے دیتا ہے۔ 65535 (0xFFFF) = سیٹ نہیں۔", "Detik UPS menunggu sebelum menyalakan stopkontaknya saat dihidupkan atau saat jala-jala kembali setelah pemadaman. Memberi waktu perangkat hulu (router, NAS) stabil sebelum sisanya menyala. 65535 (0xFFFF) = tidak diatur.", "Sekunden, die die USV beim Einschalten oder bei Netzrückkehr nach einer Abschaltung wartet, bevor sie die Steckdosen versorgt. Lässt vorgelagerte Geräte (Router, NAS) hochfahren, bevor der Rest startet. 65535 (0xFFFF) = nicht gesetzt.", "UPS 起動時、またはシャットダウン後の復電時にコンセントへ給電するまで待つ秒数。上流機器（ルーター、NAS）が安定してから他を起動できます。65535 (0xFFFF) = 未設定。", "चालू होताना किंवा शटडाउननंतर वीज परत आल्यावर आउटलेटला वीज देण्यापूर्वी UPS किती सेकंद थांबेल. अपस्ट्रीम उपकरणे (राउटर, NAS) स्थिर होऊ देते. 65535 (0xFFFF) = सेट नाही.", "ఆన్ అయినపుడు లేదా షట్‌డౌన్ తర్వాత మెయిన్స్ తిరిగి వచ్చినపుడు అవుట్‌లెట్లకు విద్యుత్ ఇచ్చే ముందు UPS వేచి ఉండే సెకన్లు. అప్‌స్ట్రీమ్ పరికరాలు (రౌటర్, NAS) స్థిరపడేలా చేస్తుంది. 65535 (0xFFFF) = సెట్ కాలేదు.", "UPS açıldığında veya kapatma sonrası şebeke geri geldiğinde prizleri beslemeden önce beklediği saniye. Üst akış cihazların (yönlendirici, NAS) oturmasına izin verir. 65535 (0xFFFF) = ayarlı değil.", "இயக்கும்போது அல்லது நிறுத்தத்திற்குப் பின் மின்சாரம் திரும்பும்போது இணைப்புகளுக்கு மின்சாரம் தரும் முன் UPS காத்திருக்கும் நொடிகள். மேல்நிலை சாதனங்கள் (ரூட்டர், NAS) நிலைபெற உதவும். 65535 (0xFFFF) = அமைக்கப்படவில்லை.", "Số giây UPS chờ trước khi cấp điện cho ổ cắm khi bật hoặc khi lưới trở lại sau ngắt. Cho thiết bị đầu nguồn (router, NAS) ổn định trước khi phần còn lại khởi động. 65535 (0xFFFF) = chưa đặt.", "UPS가 켜질 때 또는 차단 후 입력 전원이 복귀할 때 콘센트에 전원을 공급하기 전 대기하는 초. 상위 장비(라우터, NAS)가 안정된 뒤 나머지를 켤 수 있습니다. 65535 (0xFFFF) = 미설정." },
        ["help_poll"] = new[] { "How often the UPS is read over USB. Lower = faster alerts and denser charts, more log/DB entries.", "Ogni quanti secondi viene letto l'UPS via USB. Più basso = allarmi più rapidi e grafici più fitti, ma più righe di log/DB.", "通过 USB 读取 UPS 的频率。数值越小，报警越快、图表越密，但日志/数据库条目更多。", "USB से UPS को कितनी बार पढ़ा जाए। कम = तेज़ अलर्ट और घने चार्ट, अधिक लॉग/DB प्रविष्टियाँ।", "Cada cuántos segundos se lee el SAI por USB. Menor = alertas más rápidas y gráficos más densos, más registros.", "Fréquence de lecture de l'onduleur par USB. Plus bas = alertes plus rapides et courbes plus denses, mais plus d'entrées journal/BD.", "معدل قراءة الجهاز عبر USB. أقل = تنبيهات أسرع ورسوم أكثر كثافة، وسجلات أكثر.", "USB দিয়ে UPS কত ঘন ঘন পড়া হবে। কম = দ্রুত সতর্কতা ও ঘন চার্ট, বেশি লগ/DB এন্ট্রি।", "Frequência de leitura do UPS por USB. Menor = alertas mais rápidos e gráficos mais densos, mais registos.", "Как часто ИБП опрашивается по USB. Меньше = быстрее оповещения и плотнее графики, но больше записей в лог/БД.", "USB سے UPS کتنی بار پڑھا جائے۔ کم = تیز الرٹ اور گھنے چارٹ، زیادہ لاگ/DB اندراجات۔", "Seberapa sering UPS dibaca lewat USB. Lebih rendah = peringatan lebih cepat dan grafik lebih rapat, lebih banyak entri log/DB.", "Wie oft die USV per USB gelesen wird. Niedriger = schnellere Alarme und dichtere Diagramme, mehr Log-/DB-Einträge.", "USB 経由で UPS を読み取る間隔。短いほど警報が速くグラフが密になりますが、ログ/DB の件数が増えます。", "USB ने UPS किती वेळा वाचावा. कमी = जलद अलर्ट व दाट चार्ट, जास्त लॉग/DB नोंदी.", "USB ద్వారా UPS ఎంత తరచుగా చదవాలి. తక్కువ = వేగవంతమైన అలర్ట్‌లు, దట్టమైన చార్టులు, ఎక్కువ లాగ్/DB ఎంట్రీలు.", "UPS'in USB üzerinden ne sıklıkla okunacağı. Düşük = daha hızlı uyarı ve daha yoğun grafik, daha çok günlük/DB kaydı.", "USB வழியாக UPS எத்தனை நொடிக்கு ஒருமுறை வாசிக்கப்படும். குறைவு = விரைவு எச்சரிக்கை, அடர்த்தியான வரைபடம், அதிக பதிவுகள்.", "Tần suất đọc UPS qua USB. Thấp hơn = cảnh báo nhanh và biểu đồ dày hơn, nhiều bản ghi log/DB hơn.", "USB로 UPS를 읽는 주기. 짧을수록 경보가 빠르고 차트가 촘촘해지지만 로그/DB 항목이 늘어납니다." },
        ["help_warn_charge"] = new[] { "On battery only: when charge drops to this % a Warning notification is raised. No action is taken.", "Solo in batteria: quando la carica scende a questa % viene inviata una notifica di Avviso. Nessuna azione.", "仅电池供电时：电量降至此百分比时发出警告通知。不执行任何操作。", "केवल बैटरी पर: चार्ज इस % तक गिरने पर चेतावनी सूचना। कोई क्रिया नहीं।", "Solo en batería: cuando la carga baja a este % se emite un aviso. Sin acción.", "Sur batterie seulement : quand la charge descend à ce % une notification d'avertissement est émise. Aucune action.", "على البطارية فقط: عند انخفاض الشحن إلى هذه النسبة يُصدر تنبيه تحذيري. لا إجراء.", "কেবল ব্যাটারিতে: চার্জ এই % এ নামলে সতর্কতা বিজ্ঞপ্তি। কোনো পদক্ষেপ নয়।", "Só em bateria: quando a carga desce a esta % é emitido um aviso. Sem ação.", "Только на батарее: при падении заряда до этого % выдаётся предупреждение. Без действий.", "صرف بیٹری پر: چارج اس % تک گرنے پر انتباہ نوٹیفکیشن۔ کوئی کارروائی نہیں۔", "Hanya saat baterai: saat daya turun ke % ini, notifikasi Peringatan dikirim. Tidak ada tindakan.", "Nur im Batteriebetrieb: fällt die Ladung auf diesen %-Wert, wird eine Warnung gemeldet. Keine Aktion.", "バッテリー運転時のみ：残量がこの % まで下がると警告通知。動作は行いません。", "फक्त बॅटरीवर: चार्ज या % वर आल्यास इशारा सूचना. कोणतीही कृती नाही.", "బ్యాటరీపై మాత్రమే: ఛార్జ్ ఈ % కి తగ్గితే హెచ్చరిక నోటిఫికేషన్. చర్య లేదు.", "Yalnızca aküde: şarj bu %'ye düştüğünde Uyarı bildirimi verilir. İşlem yapılmaz.", "மின்கலத்தில் மட்டும்: சார்ஜ் இந்த % க்கு குறைந்தால் எச்சரிக்கை அறிவிப்பு. செயல் இல்லை.", "Chỉ khi chạy pin: khi pin giảm tới % này sẽ có thông báo Cảnh báo. Không hành động.", "배터리 운전 시에만: 충전율이 이 % 이하로 내려가면 경고 알림. 동작은 없습니다." },
        ["help_warn_rt"] = new[] { "On battery only: when estimated runtime drops to this many seconds a Warning notification is raised.", "Solo in batteria: quando l'autonomia stimata scende a questi secondi viene inviata una notifica di Avviso.", "仅电池供电时：预计续航降至此秒数时发出警告通知。", "केवल बैटरी पर: अनुमानित बैकअप समय इतने सेकंड तक गिरने पर चेतावनी सूचना।", "Solo en batería: cuando la autonomía estimada baja a estos segundos se emite un aviso.", "Sur batterie seulement : quand l'autonomie estimée descend à ce nombre de secondes une notification d'avertissement est émise.", "على البطارية فقط: عند انخفاض زمن التشغيل المقدر إلى هذه الثواني يُصدر تنبيه تحذيري.", "কেবল ব্যাটারিতে: আনুমানিক ব্যাকআপ সময় এই সেকেন্ডে নামলে সতর্কতা বিজ্ঞপ্তি।", "Só em bateria: quando a autonomia estimada desce a estes segundos é emitido um aviso.", "Только на батарее: при падении расчётного времени работы до этого числа секунд выдаётся предупреждение.", "صرف بیٹری پر: تخمینی بیک اپ وقت ان سیکنڈ تک گرنے پر انتباہ نوٹیفکیشن۔", "Hanya saat baterai: saat estimasi waktu cadangan turun ke detik ini, notifikasi Peringatan dikirim.", "Nur im Batteriebetrieb: fällt die geschätzte Restlaufzeit auf diese Sekunden, wird eine Warnung gemeldet.", "バッテリー運転時のみ：推定稼働時間がこの秒数まで下がると警告通知。", "फक्त बॅटरीवर: अंदाजित बॅकअप वेळ या सेकंदांवर आल्यास इशारा सूचना.", "బ్యాటరీపై మాత్రమే: అంచనా బ్యాకప్ సమయం ఈ సెకన్లకు తగ్గితే హెచ్చరిక నోటిఫికేషన్.", "Yalnızca aküde: tahmini çalışma süresi bu saniyeye düştüğünde Uyarı bildirimi verilir.", "மின்கலத்தில் மட்டும்: மதிப்பிட்ட இயக்க நேரம் இந்த நொடிகளுக்கு குறைந்தால் எச்சரிக்கை அறிவிப்பு.", "Chỉ khi chạy pin: khi thời gian dự phòng ước tính giảm tới số giây này sẽ có thông báo Cảnh báo.", "배터리 운전 시에만: 예상 잔여 시간이 이 초 이하로 내려가면 경고 알림." },
        ["help_crit_charge"] = new[] { "On battery only: at this charge % the state becomes Critical and the grace timer starts toward the critical action.", "Solo in batteria: a questa % di carica lo stato diventa Critico e parte l'attesa che porta all'azione critica.", "仅电池供电时：电量到此百分比时状态变为危急，并开始执行危急操作前的等待计时。", "केवल बैटरी पर: इस चार्ज % पर स्थिति गंभीर हो जाती है और गंभीर क्रिया की ओर विलंब टाइमर शुरू होता है।", "Solo en batería: a este % de carga el estado pasa a Crítico y arranca la espera hacia la acción crítica.", "Sur batterie seulement : à ce % de charge l'état devient Critique et le délai avant l'action critique démarre.", "على البطارية فقط: عند هذه النسبة تصبح الحالة حرجة ويبدأ مؤقت المهلة نحو الإجراء الحرج.", "কেবল ব্যাটারিতে: এই চার্জ % এ অবস্থা ক্রিটিক্যাল হয় এবং ক্রিটিক্যাল অ্যাকশনের দিকে বিলম্ব টাইমার শুরু হয়।", "Só em bateria: a esta % de carga o estado passa a Crítico e começa a espera para a ação crítica.", "Только на батарее: при этом % заряда состояние становится критическим и запускается отсчёт до критического действия.", "صرف بیٹری پر: اس چارج % پر حالت نازک ہو جاتی ہے اور نازک کارروائی کی طرف انتظار ٹائمر شروع ہوتا ہے۔", "Hanya saat baterai: pada % daya ini status menjadi Kritis dan penghitung tenggang menuju tindakan kritis dimulai.", "Nur im Batteriebetrieb: bei diesem Ladestand wird der Zustand Kritisch und die Wartezeit bis zur kritischen Aktion beginnt.", "バッテリー運転時のみ：この残量 % で状態が「危険」になり、危険時動作までの待機タイマーが始まります。", "फक्त बॅटरीवर: या चार्ज % वर स्थिती गंभीर होते आणि गंभीर कृतीकडे प्रतीक्षा टाइमर सुरू होतो.", "బ్యాటరీపై మాత్రమే: ఈ ఛార్జ్ % వద్ద స్థితి క్రిటికల్ అవుతుంది, క్రిటికల్ చర్య వైపు వేచి ఉండే టైమర్ మొదలవుతుంది.", "Yalnızca aküde: bu şarj %'sinde durum Kritik olur ve kritik eyleme giden bekleme sayacı başlar.", "மின்கலத்தில் மட்டும்: இந்த சார்ஜ் % இல் நிலை நெருக்கடியாகி, நெருக்கடி செயலுக்கான காத்திருப்பு நேரம் தொடங்கும்.", "Chỉ khi chạy pin: ở % pin này trạng thái thành Nguy cấp và bộ đếm chờ tới hành động nguy cấp bắt đầu.", "배터리 운전 시에만: 이 충전율에서 상태가 위험으로 바뀌고 위험 동작까지의 대기 타이머가 시작됩니다." },
        ["help_crit_rt"] = new[] { "On battery only: at this estimated runtime (seconds) the state becomes Critical. Either critical threshold is enough.", "Solo in batteria: a questa autonomia stimata (secondi) lo stato diventa Critico. Basta una delle due soglie critiche.", "仅电池供电时：预计续航到此秒数时状态变为危急。任一危急阈值满足即可。", "केवल बैटरी पर: इस अनुमानित बैकअप समय (सेकंड) पर स्थिति गंभीर हो जाती है। कोई भी एक गंभीर सीमा पर्याप्त है।", "Solo en batería: con esta autonomía estimada (segundos) el estado pasa a Crítico. Basta con uno de los dos umbrales críticos.", "Sur batterie seulement : à cette autonomie estimée (secondes) l'état devient Critique. L'un des deux seuils critiques suffit.", "على البطارية فقط: عند هذا زمن التشغيل المقدر (ثوانٍ) تصبح الحالة حرجة. يكفي أحد العتبتين الحرجتين.", "কেবল ব্যাটারিতে: এই আনুমানিক ব্যাকআপ সময়ে (সেকেন্ড) অবস্থা ক্রিটিক্যাল হয়। যেকোনো একটি ক্রিটিক্যাল সীমাই যথেষ্ট।", "Só em bateria: a esta autonomia estimada (segundos) o estado passa a Crítico. Basta um dos dois limites críticos.", "Только на батарее: при этом расчётном времени работы (сек) состояние становится критическим. Достаточно любого из двух критических порогов.", "صرف بیٹری پر: اس تخمینی بیک اپ وقت (سیکنڈ) پر حالت نازک ہو جاتی ہے۔ دونوں نازک حدوں میں سے ایک کافی ہے۔", "Hanya saat baterai: pada estimasi waktu cadangan ini (detik) status menjadi Kritis. Salah satu ambang kritis sudah cukup.", "Nur im Batteriebetrieb: bei dieser geschätzten Restlaufzeit (Sekunden) wird der Zustand Kritisch. Eine der beiden kritischen Schwellen genügt.", "バッテリー運転時のみ：推定稼働時間がこの秒数で状態が「危険」になります。2 つの危険しきい値のどちらか一方で十分です。", "फक्त बॅटरीवर: या अंदाजित बॅकअप वेळेवर (सेकंद) स्थिती गंभीर होते. दोन गंभीर मर्यादांपैकी एक पुरेशी.", "బ్యాటరీపై మాత్రమే: ఈ అంచనా బ్యాకప్ సమయం (సెకన్లు) వద్ద స్థితి క్రిటికల్ అవుతుంది. రెండు క్రిటికల్ పరిమితుల్లో ఒకటి సరిపోతుంది.", "Yalnızca aküde: bu tahmini çalışma süresinde (saniye) durum Kritik olur. İki kritik eşikten biri yeterlidir.", "மின்கலத்தில் மட்டும்: இந்த மதிப்பிட்ட இயக்க நேரத்தில் (நொடிகள்) நிலை நெருக்கடியாகும். இரு நெருக்கடி வரம்புகளில் ஒன்று போதும்.", "Chỉ khi chạy pin: ở thời gian dự phòng ước tính này (giây) trạng thái thành Nguy cấp. Một trong hai ngưỡng nguy cấp là đủ.", "배터리 운전 시에만: 예상 잔여 시간이 이 초가 되면 상태가 위험으로 바뀝니다. 두 위험 임계값 중 하나만 충족되면 됩니다." },
        ["help_grace"] = new[] { "Seconds the Critical state must persist before the critical action fires. Resets if mains returns. Gives time to save work.", "Secondi per cui lo stato Critico deve persistere prima che scatti l'azione critica. Si azzera se torna la rete. Dà tempo di salvare il lavoro.", "危急状态必须持续多少秒后才执行危急操作。市电恢复则重置。留出保存工作的时间。", "गंभीर क्रिया चलने से पहले गंभीर स्थिति कितने सेकंड बनी रहे। बिजली लौटने पर रीसेट। काम सहेजने का समय देता है।", "Segundos que debe persistir el estado Crítico antes de ejecutar la acción crítica. Se reinicia si vuelve la red. Da tiempo para guardar el trabajo.", "Secondes pendant lesquelles l'état Critique doit persister avant l'action critique. Remis à zéro si le secteur revient. Laisse le temps de sauvegarder.", "الثواني التي يجب أن تستمر فيها الحالة الحرجة قبل تنفيذ الإجراء الحرج. يُعاد ضبطها عند عودة الشبكة. يمنح وقتًا لحفظ العمل.", "ক্রিটিক্যাল অ্যাকশন চালুর আগে ক্রিটিক্যাল অবস্থা কত সেকেন্ড থাকতে হবে। মেইন ফিরলে রিসেট। কাজ সংরক্ষণের সময় দেয়।", "Segundos que o estado Crítico deve persistir antes de executar a ação crítica. Reinicia se a rede voltar. Dá tempo para guardar o trabalho.", "Сколько секунд должно сохраняться критическое состояние до выполнения критического действия. Сбрасывается при возврате сети. Даёт время сохранить работу.", "نازک کارروائی سے پہلے نازک حالت کتنے سیکنڈ برقرار رہے۔ مینز واپس آنے پر ری سیٹ۔ کام محفوظ کرنے کا وقت دیتا ہے۔", "Detik status Kritis harus bertahan sebelum tindakan kritis dijalankan. Direset jika jala-jala kembali. Memberi waktu menyimpan pekerjaan.", "Sekunden, die der kritische Zustand anhalten muss, bevor die kritische Aktion ausgelöst wird. Wird bei Netzrückkehr zurückgesetzt. Zeit zum Speichern der Arbeit.", "危険状態がこの秒数続いた後に危険時動作を実行します。復電すればリセットされます。作業を保存する時間を確保します。", "गंभीर कृती चालण्यापूर्वी गंभीर स्थिती किती सेकंद टिकावी. वीज परत आल्यास रीसेट. काम जतन करण्यास वेळ देते.", "క్రిటికల్ చర్య జరగడానికి ముందు క్రిటికల్ స్థితి ఎన్ని సెకన్లు కొనసాగాలి. మెయిన్స్ తిరిగి వస్తే రీసెట్. పనిని సేవ్ చేయడానికి సమయం ఇస్తుంది.", "Kritik eylem tetiklenmeden önce Kritik durumun sürmesi gereken saniye. Şebeke gelirse sıfırlanır. İşi kaydetmek için zaman verir.", "நெருக்கடி செயல் நடைபெறும் முன் நெருக்கடி நிலை நீடிக்க வேண்டிய நொடிகள். மின்சாரம் திரும்பினால் மீட்டமைப்பு. வேலையை சேமிக்க நேரம் தரும்.", "Số giây trạng thái Nguy cấp phải kéo dài trước khi hành động nguy cấp chạy. Đặt lại nếu lưới trở lại. Cho thời gian lưu công việc.", "위험 상태가 이 초 동안 지속되어야 위험 동작이 실행됩니다. 입력 전원이 복귀하면 초기화됩니다. 작업을 저장할 시간을 줍니다." },
        ["help_action"] = new[] { "What happens when the grace period expires: Simulate = log + notification only; Hibernate = PC hibernates (state saved to disk); Shut down = full PC shutdown.", "Cosa succede allo scadere dell'attesa: Simulazione = solo log e notifica; Iberna = il PC va in ibernazione (stato salvato su disco); Spegni = arresto completo del PC.", "等待期结束后执行：仅模拟 = 只记录日志和通知；休眠 = 电脑休眠（状态保存到磁盘）；关机 = 完全关闭电脑。", "विलंब समाप्त होने पर: सिमुलेशन = केवल लॉग और सूचना; हाइबरनेट = PC हाइबरनेट (स्थिति डिस्क पर सहेजी); बंद = PC पूर्ण शटडाउन।", "Qué ocurre al expirar la espera: Simular = solo registro y notificación; Hibernar = el PC hiberna (estado guardado en disco); Apagar = apagado completo del PC.", "Ce qui se passe à l'expiration du délai : Simuler = journal et notification seulement ; Veille prolongée = le PC hiberne (état sauvegardé sur disque) ; Éteindre = arrêt complet du PC.", "ما يحدث عند انتهاء المهلة: محاكاة = سجل وإشعار فقط؛ إسبات = يدخل الحاسوب في الإسبات (الحالة محفوظة على القرص)؛ إيقاف = إيقاف كامل للحاسوب.", "বিলম্ব শেষে কী হবে: সিমুলেশন = কেবল লগ ও বিজ্ঞপ্তি; হাইবারনেট = PC হাইবারনেট (অবস্থা ডিস্কে সংরক্ষিত); শাটডাউন = PC সম্পূর্ণ বন্ধ।", "O que acontece ao terminar a espera: Simular = só registo e notificação; Hibernar = o PC hiberna (estado guardado no disco); Desligar = encerramento completo do PC.", "Что происходит по истечении ожидания: Симуляция = только лог и уведомление; Гибернация = ПК уходит в гибернацию (состояние сохранено на диск); Выключение = полное выключение ПК.", "انتظار ختم ہونے پر: سمولیشن = صرف لاگ اور نوٹیفکیشن؛ ہائبرنیٹ = PC ہائبرنیٹ (حالت ڈسک پر محفوظ)؛ شٹ ڈاؤن = PC مکمل بند۔", "Yang terjadi saat tenggang habis: Simulasi = hanya log dan notifikasi; Hibernasi = PC hibernasi (status disimpan ke disk); Matikan = PC dimatikan sepenuhnya.", "Was nach Ablauf der Wartezeit passiert: Simulation = nur Log und Benachrichtigung; Ruhezustand = PC geht in den Ruhezustand (Zustand auf Platte gesichert); Herunterfahren = vollständiges Abschalten des PCs.", "待機時間満了後の動作：シミュレーション = ログと通知のみ；休止状態 = PC を休止（状態をディスクに保存）；シャットダウン = PC を完全に停止。", "प्रतीक्षा संपल्यावर: सिम्युलेशन = फक्त लॉग व सूचना; हायबरनेट = PC हायबरनेट (स्थिती डिस्कवर जतन); बंद = PC पूर्ण बंद.", "వేచి ఉండే సమయం ముగిశాక: సిమ్యులేషన్ = లాగ్, నోటిఫికేషన్ మాత్రమే; హైబర్నేట్ = PC హైబర్నేట్ (స్థితి డిస్క్‌లో సేవ్); షట్‌డౌన్ = PC పూర్తిగా ఆఫ్.", "Bekleme süresi dolduğunda: Simülasyon = yalnızca günlük ve bildirim; Hazırda beklet = PC hazırda bekletilir (durum diske kaydedilir); Kapat = PC tamamen kapatılır.", "காத்திருப்பு முடிந்தபின்: உருவகப்படுத்தல் = பதிவு மற்றும் அறிவிப்பு மட்டும்; உறக்கநிலை = PC உறக்கநிலை (நிலை வட்டில் சேமிப்பு); அணை = PC முழுமையாக அணைப்பு.", "Khi hết thời gian chờ: Mô phỏng = chỉ ghi log và thông báo; Ngủ đông = PC ngủ đông (trạng thái lưu vào đĩa); Tắt = tắt hẳn PC.", "대기 시간 만료 시: 시뮬레이션 = 로그와 알림만; 최대 절전 = PC 최대 절전(상태를 디스크에 저장); 종료 = PC 완전 종료." },
        ["help_lang"] = new[] { "Interface language. Auto follows the Windows display language. Takes effect after restarting the app.", "Lingua dell'interfaccia. Auto segue la lingua di Windows. Ha effetto dopo il riavvio dell'app.", "界面语言。自动 = 跟随 Windows 显示语言。重启应用后生效。", "इंटरफ़ेस भाषा। ऑटो Windows की भाषा का अनुसरण करता है। ऐप पुनः आरंभ के बाद लागू।", "Idioma de la interfaz. Auto sigue el idioma de Windows. Se aplica al reiniciar la app.", "Langue de l'interface. Auto suit la langue de Windows. Prend effet après redémarrage de l'application.", "لغة الواجهة. تلقائي يتبع لغة Windows. يسري بعد إعادة تشغيل التطبيق.", "ইন্টারফেস ভাষা। অটো Windows-এর ভাষা অনুসরণ করে। অ্যাপ পুনরায় চালু করলে কার্যকর।", "Idioma da interface. Auto segue o idioma do Windows. Aplica-se após reiniciar a app.", "Язык интерфейса. Авто следует языку Windows. Применяется после перезапуска приложения.", "انٹرفیس زبان۔ آٹو Windows کی زبان کی پیروی کرتا ہے۔ ایپ دوبارہ شروع کرنے پر لاگو۔", "Bahasa antarmuka. Otomatis mengikuti bahasa Windows. Berlaku setelah aplikasi dimulai ulang.", "Sprache der Oberfläche. Auto folgt der Windows-Anzeigesprache. Wirksam nach Neustart der App.", "表示言語。自動は Windows の表示言語に従います。アプリ再起動後に有効。", "इंटरफेस भाषा. ऑटो Windows भाषेचे अनुसरण करते. अ‍ॅप पुन्हा सुरू केल्यावर लागू.", "ఇంటర్‌ఫేస్ భాష. ఆటో Windows భాషను అనుసరిస్తుంది. యాప్ పునఃప్రారంభం తర్వాత అమలు.", "Arayüz dili. Otomatik, Windows görüntü dilini izler. Uygulama yeniden başlatıldığında etkinleşir.", "இடைமுக மொழி. தானியங்கு Windows மொழியைப் பின்பற்றும். செயலி மறுதொடக்கத்திற்குப் பின் செயல்படும்.", "Ngôn ngữ giao diện. Tự động theo ngôn ngữ Windows. Có hiệu lực sau khi khởi động lại ứng dụng.", "인터페이스 언어. 자동은 Windows 표시 언어를 따릅니다. 앱을 다시 시작하면 적용됩니다." },
    };
}
